package main

import (
	"fmt"
	"os"

	"github.com/golang-jwt/jwt/v5"
)

// In a production environment, replace this with your actual OpenSSL Public Key.
// This key verifies that the license was generated by your secure backend.
const publicKeyPEM = `-----BEGIN PUBLIC KEY-----
YOUR_PUBLIC_KEY_HERE
-----END PUBLIC KEY-----`

// VerifyLicense checks the cryptographic signature of the license file.
func VerifyLicense() error {
	// Bypass mechanism for local development and testing
	if os.Getenv("SKIP_LICENSE_CHECK") == "true" {
		return nil
	}

	keyData, err := os.ReadFile("/app/data/license.key")
	if err != nil {
		return fmt.Errorf("license.key file not found: %v", err)
	}

	pubKey, err := jwt.ParseRSAPublicKeyFromPEM([]byte(publicKeyPEM))
	if err != nil {
		return fmt.Errorf("failed to parse public key: %v", err)
	}

	token, err := jwt.Parse(string(keyData), func(token *jwt.Token) (interface{}, error) {
		if _, ok := token.Method.(*jwt.SigningMethodRSA); !ok {
			return nil, fmt.Errorf("unexpected signing method: %v", token.Header["alg"])
		}
		return pubKey, nil
	})

	if err != nil || !token.Valid {
		return fmt.Errorf("invalid or expired license key")
	}

	return nil
}